#!/usr/bin/env python3
"""FS3 v157 - Subach sound, guns in time, scan loop, gas miners fire,
hull shields, Ursa/Medusa dorsal turret, Ares nose gun.

    Sound    the Mekhu/Subach (hl7) has its own sound (wpn_mekhu) instead
             of the Prometheus one. The player's guns cut their oldest
             sound short instead of leaving a shot out, so every shot is
             heard in time (the Dante was missing every third). The scan
             beep repeats for as long as a scan runs and stops with it.
    M39      the gas miners fire their guns at you while they run (aimed by
             eye - nobody holds a lock in the gas).
    Shields  small ships (the player's too) no longer show an oval: the
             shield flares along the hull's own outline, Vasudan yellow
             orange, Terran blue white, Shivan red white.
    Turret   the gun on the back of the Ursa and the Medusa is a turret of
             its own, as in FreeSpace: it fires by itself at the nearest
             hostile in reach in the half circle above the hull, also when
             the player flies the ship. Always a Subach, at half the weight
             of one Subach barrel. Enemy and allied Ursas and Medusas have
             it too. Their main guns lose that barrel (Ursa 3, Medusa 1).
    Ares     a third primary gun in her nose.

Needs v156. Edits src/12_audio.js, src/30_waves.js, src/40_world.js,
src/50_combat.js, src/60_effects.js and hlp_mounts_final.json in place,
and writes the updated fieldsim.js. Run assemble.py afterwards.
"""
import base64
import sys

if "MUSIC_LIST" not in open("src/12_audio.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v156 einspielen.")
if "SND_STEAL" in open("src/12_audio.js", encoding="utf-8").read():
    sys.exit("Abbruch: v157 ist schon eingespielt.")

FIELDSIM = ""

import json
F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, label, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d." % (label, n, count))
    F[p] = F[p].replace(old, new)

AU, EF, CB, WV, WO, UI = "src/12_audio.js", "src/60_effects.js", "src/50_combat.js", "src/30_waves.js", "src/40_world.js", "src/70_ui.js"

# ── Sound: the Subach, the player's guns in time, the scan loop ──
rep(AU, "const PRI_SND = {prometheus:'wpn_prometheus', scatter:'wpn_sidhe', dante:'wpn_dante'};",
        "const PRI_SND = {prometheus:'wpn_prometheus', hl7:'wpn_subach', scatter:'wpn_sidhe', dante:'wpn_dante'};\n"
        "// The player's own guns: every shot is heard. When all voices of one\n"
        "// are busy the oldest is cut short instead of the new shot left out -\n"
        "// a Dante sound is longer than the time between two Dante shots.\n"
        "const SND_STEAL = {wpn_prometheus:1, wpn_subach:1, wpn_sidhe:1, wpn_dante:1};", "pri snd")
rep(AU, "  scan_start:0.80, scan_done:0.90,", "  scan_start:0.80, scan_done:0.90, scan_loop:0.70,", "scan mix")
rep(AU, "let SND_BEAMS = [];            // {e, b, src, c, base} for every beam loop\n",
        "let SND_BEAMS = [];            // {e, b, src, c, base} for every beam loop\n"
        "const SND_SRCS = {};           // channel -> sources sounding, oldest first\n"
        "let SND_SCANS = [];            // scan loops: {o, src}\n", "srcs")
rep(AU, "  const ch = mix || name;\n  if((SND_PLAYING[ch]||0) >= (SND_VOICES[ch] || 4)) return null;\n",
        "  const ch = mix || name;\n"
        "  if((SND_PLAYING[ch]||0) >= (SND_VOICES[ch] || 4)){\n"
        "    if(!SND_STEAL[ch] || !(SND_SRCS[ch]||[]).length) return null;\n"
        "    const old = SND_SRCS[ch].shift();\n"
        "    old._stolen = true;\n"
        "    SND_PLAYING[ch] = Math.max(0, SND_PLAYING[ch]-1);\n"
        "    if(!old.loop) SND_ALL = Math.max(0, SND_ALL-1);\n"
        "    sndStop(old);\n"
        "  }\n", "steal")
rep(AU, "  if(!loop && SND_LAST[ch] != null && now - SND_LAST[ch] < (SND_GAP[ch] || 0.03)) return null;\n",
        "  if(!loop && !SND_STEAL[ch] && SND_LAST[ch] != null && now - SND_LAST[ch] < (SND_GAP[ch] || 0.03)) return null;\n", "gap steal")
rep(AU, "  SND_PLAYING[ch] = (SND_PLAYING[ch]||0) + 1;\n  if(!loop) SND_ALL++;\n  src.onended = function(){\n    SND_PLAYING[ch] = Math.max(0, (SND_PLAYING[ch]||1) - 1);\n    if(!loop) SND_ALL = Math.max(0, SND_ALL - 1);\n  };\n",
        "  SND_PLAYING[ch] = (SND_PLAYING[ch]||0) + 1;\n  if(!loop) SND_ALL++;\n  (SND_SRCS[ch] = SND_SRCS[ch] || []).push(src);\n"
        "  src.onended = function(){\n"
        "    const l = SND_SRCS[ch], k = l ? l.indexOf(src) : -1;\n"
        "    if(k >= 0) l.splice(k, 1);\n"
        "    if(src._stolen) return;          // already counted off when it was cut\n"
        "    SND_PLAYING[ch] = Math.max(0, (SND_PLAYING[ch]||1) - 1);\n"
        "    if(!loop) SND_ALL = Math.max(0, SND_ALL - 1);\n  };\n", "onended")
rep(AU, "// Scans: the short sound when a scan begins (again after it was broken\n"
        "// off), the long one when it is done. o is the ship or the subsystem.\n"
        "function sndScanStep(o, x, y, running){\n"
        "  if(running && !o._sndScan){ o._sndScan = true; sndPlay('scan_start', x, 1, y); }\n"
        "  else if(!running) o._sndScan = false;\n}\n",
        "// Scans: the short beep repeats for as long as a scan runs and stops when\n"
        "// it is done or broken off; the long sound follows when it is done.\n"
        "// o is the ship or the subsystem. Called every step while scanning\n"
        "// (running), and once when it stops.\n"
        "function sndScanStep(o, x, y, running){\n"
        "  if(running){\n"
        "    o._sndScanT = fc;\n"
        "    if(!o._sndScan){\n"
        "      o._sndScan = true;\n"
        "      const src = sndStart('scan_start', x, 1, true, 'scan_loop', y);\n"
        "      if(src) SND_SCANS.push({o:o, src:src});\n"
        "    }\n"
        "  } else if(o._sndScan){\n"
        "    o._sndScan = false;\n"
        "    for(let i=SND_SCANS.length-1; i>=0; i--)\n"
        "      if(SND_SCANS[i].o === o){ sndStop(SND_SCANS[i].src); SND_SCANS.splice(i, 1); }\n"
        "  }\n}\n", "scan loop")
rep(AU, "    sndStop(s.src);\n    sndStart('beam_'+s.c+'_down', e.x, 1, false, 'beam_down', e.y);\n    SND_BEAMS.splice(i, 1);\n  }\n}\n",
        "    sndStop(s.src);\n    sndStart('beam_'+s.c+'_down', e.x, 1, false, 'beam_down', e.y);\n    SND_BEAMS.splice(i, 1);\n  }\n"
        "  // A scan loop whose scan was not continued this step (target gone,\n"
        "  // wave over) stops by itself.\n"
        "  for(let i=SND_SCANS.length-1; i>=0; i--){\n"
        "    const s = SND_SCANS[i];\n"
        "    if(fc - (s.o._sndScanT||0) > 2){ sndStop(s.src); s.o._sndScan = false; SND_SCANS.splice(i, 1); }\n"
        "  }\n}\n", "scan sweep")
rep(AU, "  for(const s of SND_BEAMS) sndStop(s.src);\n  SND_BEAMS = [];\n",
        "  for(const s of SND_BEAMS) sndStop(s.src);\n  SND_BEAMS = [];\n"
        "  for(const s of SND_SCANS){ sndStop(s.src); s.o._sndScan = false; }\n  SND_SCANS = [];\n", "all off scans")
# The scan ends in the done branches too.
rep(WV, "        e.scanned = true;\n        score += 200;\n        sndPlay('scan_done', e.x, 1, e.y);\n",
        "        e.scanned = true;\n        score += 200;\n        sndScanStep(e, 0, 0, false);\n        sndPlay('scan_done', e.x, 1, e.y);\n", "scan done stop")
rep(WV, "        s.scanned = true; score += 100;\n        sndPlay('scan_done', e.x, 1, e.y);\n",
        "        s.scanned = true; score += 100;\n        sndScanStep(s, 0, 0, false);\n        sndPlay('scan_done', e.x, 1, e.y);\n", "sub scan done stop")

# ── M39: the gas miners fire their guns while they run ──
rep(EF, "      if(e.dockTo) continue;\n      // Being shot at, not damage, is what sends it running.",
        "      if(e.dockTo) continue;\n      if(FREIGHTER_GUNS[e.img]) freighterGuns(e);\n      // Being shot at, not damage, is what sends it running.", "miner fire call")
rep(CB, "// Damage of one primary volley. A ship with four barrels should\n",
        "// Freighters that carry guns (the gas miners): their primary mounts fire\n"
        "// like a slow cruiser battery, at allied capital ships first, else the\n"
        "// player. No missiles and no flak - they are working ships.\n"
        "const FREIGHTER_GUNS = {gmzephyrus:1, gmanuket:1, gmrahu:1};\n"
        "const FREIGHTER_GUN_RATE = [150, 240];\n"
        "function freighterGuns(e){\n"
        "  if(e.dead || e.warp>0 || e.warpOut>0 || e.noFire) return;\n"
        "  if(!subOK(e,'weapons')) return;\n"
        "  const m = mountsFor(e.img);\n"
        "  if(!m || !m.primary || !m.primary.length) return;\n"
        "  if(!e.gunT) e.gunT = m.primary.map(function(){ return (rndR(FREIGHTER_GUN_RATE)*Math.random())|0; });\n"
        "  const pts = entMounts(e, 'primary');\n"
        "  if(!pts) return;\n"
        "  for(let i=0;i<pts.length && i<e.gunT.length;i++){\n"
        "    if(--e.gunT[i] > 0) continue;\n"
        "    e.gunT[i] = rndR(FREIGHTER_GUN_RATE)|0;\n"
        "    // Aimed by eye: in the gas of M39 nobody holds a lock, but these\n"
        "    // gunners still see the ship they are shooting at.\n"
        "    const gt = capGunTarget(e) || (GS==='playing' ? player : null);\n"
        "    if(!gt) continue;\n"
        "    sndAiShot(pts[i].x, pts[i].y);\n"
        "    eSmall(pts[i].x, pts[i].y, e.faction, Math.atan2(gt.y-pts[i].y, gt.x-pts[i].x)+(Math.random()-0.5)*0.10);\n"
        "  }\n"
        "}\n\n"
        "// Damage of one primary volley. A ship with four barrels should\n", "freighter guns")

# ── Ursa and Medusa: the dorsal turret (mounts 'turret'), always a Subach ──
rep(CB, "// Freighters that carry guns (the gas miners)",
        "// A turret of its own, as in FreeSpace (the dorsal gun of the Ursa and\n"
        "// the Medusa, mount list 'turret'): it fires by itself at the nearest\n"
        "// hostile in reach within the half circle above the hull, also when\n"
        "// the player flies the ship - he has no say over it. Always a Subach,\n"
        "// whatever the main guns are, and at half the weight of one Subach\n"
        "// barrel and a slower beat, so it helps without taking over.\n"
        "const TURRET_WPN = 'hl7', TURRET_CD = 30, TURRET_DMG = 0.5;\n"
        "function turretTick(o, isPlayer){\n"
        "  const key = isPlayer ? player.ship : o.img;\n"
        "  const m = mountsFor(key);\n"
        "  if(!m || !m.turret || !m.turret.length) return;\n"
        "  if(o.turT > 0){ o.turT--; return; }\n"
        "  const sc = isPlayer ? playerSc() : o.sc, a = o.ang || 0;\n"
        "  const pts = mountList(key, o.x, o.y, sc, o.flip||false, 'turret', a);\n"
        "  if(!pts || !pts.length) return;\n"
        "  const wp = priDef(TURRET_WPN), reach = wp.range || 330;\n"
        "  // Above the hull: the sprite's up, turned with the ship.\n"
        "  const ux = Math.sin(a), uy = -Math.cos(a);\n"
        "  const mine = isPlayer || o.side==='ally';\n"
        "  const list = mine ? enemies : [player].concat(allies);\n"
        "  let best = null, bd = reach;\n"
        "  for(const t of list){\n"
        "    if(!t || t===o || t.dead || t.warp>0 || t.warpOut>0 || t.scenery || t.invuln) continue;\n"
        "    if(t.type==='asteroid' || (mine && playerOnly(t) && !isPlayer)) continue;\n"
        "    if(t===player && GS!=='playing') continue;\n"
        "    const dx = t.x-pts[0].x, dy = t.y-pts[0].y, d = Math.hypot(dx, dy);\n"
        "    if(d >= bd || dx*ux + dy*uy < 0) continue;\n"
        "    bd = d; best = t;\n"
        "  }\n"
        "  if(!best){ o.turT = 10; return; }\n"
        "  o.turT = TURRET_CD;\n"
        "  for(const p of pts){\n"
        "    const ang = leadAngle(p.x, p.y, best, wp.spd) + (Math.random()-0.5)*0.06;\n"
        "    if(mine){\n"
        "      pBullets.push({x:p.x, y:p.y, vx:Math.cos(ang)*wp.spd, vy:Math.sin(ang)*wp.spd,\n"
        "                     w:14, h:3, dmg:volleyDmg(1)*wp.dmg*TURRET_DMG,\n"
        "                     col:wp.col, glow:wp.glow, pLife:Math.max(1, Math.round(reach/wp.spd)),\n"
        "                     ally:!isPlayer, fac:o.faction, turret:true});\n"
        "    } else {\n"
        "      eSmall(p.x, p.y, o.faction, ang, wp.spd, eVolleyDmg(1)*wp.dmg);\n"
        "    }\n"
        "  }\n"
        "  if(isPlayer) sndPlay('wpn_subach', o.x, 0.6);\n"
        "  else sndAiShot(o.x, o.y);\n"
        "}\n\n"
        "// Freighters that carry guns (the gas miners)", "turret")
rep(EF, "  if(!inJump()&&(isFiring||MOUSE.down||K['Space']||K['KeyZ'])&&--player.fT<=0){pShoot();player.fT=player.fR;}\n",
        "  if(!inJump()&&(isFiring||MOUSE.down||K['Space']||K['KeyZ'])&&--player.fT<=0){pShoot();player.fT=player.fR;}\n"
        "  if(!inJump()) turretTick(player, true);   // the dorsal gun of Ursa and Medusa\n", "player turret")
rep(EF, "      const tgt=flySmall(e);\n      if(--e.fT<=0) smallFire(e,tgt);\n      fireSecondaries(e, WPN[e.type]);\n",
        "      const tgt=flySmall(e);\n      if(--e.fT<=0) smallFire(e,tgt);\n      turretTick(e, false);\n      fireSecondaries(e, WPN[e.type]);\n", "enemy turret")
rep(WO, "      const tg = flySmall(a);\n      if(--a.fT<=0) smallFire(a, tg);\n",
        "      const tg = flySmall(a);\n      if(--a.fT<=0) smallFire(a, tg);\n      turretTick(a, false);\n", "ally turret")

# ── Shields of small ships: along the hull, in the colour of the side ──
rep(WO, "function drawShield(e){\n  if(!e.maxSh || e.shHit <= 0 || e.sh <= 0) return;\n  const img = IMGS[e.img]; if(!img) return;\n",
        "function drawShield(e){\n  if(!e.maxSh || e.shHit <= 0 || e.sh <= 0) return;\n  const img = IMGS[e.img]; if(!img) return;\n"
        "  if(hullShield(e.img, e.faction, e.x, e.y, e.sc, e.flip, e.ang||0, e.sh/e.maxSh, e.shHit)) return;\n", "shield e")
rep(WO, "  const sc = playerSc();\n  shieldBubble(player.x, player.y,",
        "  const sc = playerSc();\n"
        "  const pf = (shipStats(player.ship).fac) || 'terran';\n"
        "  if(hullShield(player.ship, pf, player.x, player.y, sc, player.flip, player.ang||0,\n"
        "                player.sh/player.maxSh, player.shHit)) return;\n"
        "  shieldBubble(player.x, player.y,", "shield player")
rep(WO, "// The shield is the ship's own outline, not an ellipse laid over it. The\n",
        "// Small ships: the shield flares along the hull's own outline when hit,\n"
        "// in the colour of the side - Vasudan yellow orange, Terran blue white,\n"
        "// Shivan red white. The skin is the sprite's silhouette, blurred outward\n"
        "// in the side's colour with a white rim just outside the edge and the\n"
        "// inside left almost clear, so the hull stays readable. Built once per\n"
        "// hull and side, at a small size (sprites are large, drawn small).\n"
        "const HULL_SH = {};\n"
        "const HULL_SH_W = 170;\n"
        "function hullShieldCol(fac){\n"
        "  if(fac==='shivan') return {glow:'#ff3b24', rim:'#fff0ea'};\n"
        "  if(fac==='vasudan' || fac==='hol') return {glow:'#ffa21f', rim:'#fff4d2'};\n"
        "  return {glow:'#48a6ff', rim:'#ffffff'};\n"
        "}\n"
        "function hullShieldSkin(key, fac){\n"
        "  const col = hullShieldCol(fac), id = key+'|'+col.glow;\n"
        "  if(HULL_SH[id] !== undefined) return HULL_SH[id];\n"
        "  const img = IMGS[key];\n"
        "  if(!img || !img.width) return null;\n"
        "  const s = Math.min(1, HULL_SH_W/img.width), P = 14;\n"
        "  const iw = Math.max(1, Math.round(img.width*s)), ih = Math.max(1, Math.round(img.height*s));\n"
        "  const w = iw+P*2, h = ih+P*2;\n"
        "  const mk = function(){ const c = document.createElement('canvas'); c.width = w; c.height = h; return c; };\n"
        "  try{\n"
        "    // Silhouette in the glow colour, and in white.\n"
        "    const sil = mk(), sc = sil.getContext('2d');\n"
        "    sc.drawImage(img, P, P, iw, ih);\n"
        "    sc.globalCompositeOperation = 'source-in'; sc.fillStyle = col.glow; sc.fillRect(0, 0, w, h);\n"
        "    const wht = mk(), wc = wht.getContext('2d');\n"
        "    wc.drawImage(img, P, P, iw, ih);\n"
        "    wc.globalCompositeOperation = 'source-in'; wc.fillStyle = col.rim; wc.fillRect(0, 0, w, h);\n"
        "    const out = mk(), oc = out.getContext('2d');\n"
        "    oc.shadowColor = col.glow;\n"
        "    for(let p=0;p<3;p++){ oc.shadowBlur = 3 + p*4; oc.drawImage(sil, 0, 0); }\n"
        "    oc.shadowBlur = 0;\n"
        "    // The rim: the white silhouette nudged a little in every direction.\n"
        "    for(let k=0;k<8;k++){\n"
        "      const r = k*Math.PI/4;\n"
        "      oc.drawImage(wht, Math.round(Math.cos(r)*1.6), Math.round(Math.sin(r)*1.6));\n"
        "    }\n"
        "    // The inside nearly clear again.\n"
        "    oc.globalCompositeOperation = 'destination-out';\n"
        "    oc.globalAlpha = 0.82; oc.drawImage(sil, 0, 0);\n"
        "    HULL_SH[id] = {cv:out, s:s, P:P, w:w, h:h};\n"
        "  }catch(ex){ HULL_SH[id] = null; }\n"
        "  return HULL_SH[id];\n"
        "}\n"
        "// Draws it; false if there is no skin (then the old bubble is drawn).\n"
        "function hullShield(key, fac, x, y, sc, flip, ang, frac, hit){\n"
        "  const k = hullShieldSkin(key, fac);\n"
        "  if(!k) return false;\n"
        "  const t = hit/SH_FLASH, base = 0.35 + 0.65*frac;\n"
        "  const f = sc/k.s;                       // skin pixels to screen\n"
        "  ctx.save();\n"
        "  ctx.globalCompositeOperation = 'lighter';\n"
        "  ctx.globalAlpha = Math.min(1, 1.25*t*base);\n"
        "  ctx.translate(x|0, y|0);\n"
        "  if(ang) ctx.rotate(ang);\n"
        "  if(flip) ctx.scale(-1, 1);\n"
        "  // A touch larger right after the hit, settling onto the hull.\n"
        "  const g = 1 + 0.06*t;\n"
        "  ctx.drawImage(k.cv, -k.w*f*g/2, -k.h*f*g/2, k.w*f*g, k.h*f*g);\n"
        "  ctx.restore();\n"
        "  return true;\n"
        "}\n\n"
        "// The shield is the ship's own outline, not an ellipse laid over it. The\n", "hull shield")

# ── Mounts: the dorsal guns of Ursa and Medusa become turrets, the Ares gets
#    a gun in her nose ──
MJ = "hlp_mounts_final.json"
load(MJ)
_m = json.loads(F[MJ])
def _move(key, dx, dy):
    lst = _m[key]["primary"]
    hit = [p for p in lst if abs(p["dx"]-dx) < 1e-6 and abs(p["dy"]-dy) < 1e-6]
    if len(hit) != 1:
        sys.exit("Abbruch (Mounts %s): Rueckenturm nicht gefunden." % key)
    lst.remove(hit[0])
    _m[key]["turret"] = [hit[0]]
if "turret" not in _m["boursa"]: _move("boursa", -0.442, -0.882)
if "turret" not in _m["bomedusa"]: _move("bomedusa", -0.383, -0.58)
_ap = _m["fiares"]["primary"]
if not any(abs(p["dx"]-0.921) < 1e-6 for p in _ap):
    _ap.append({"dx": 0.921, "dy": 0.102})
F[MJ] = json.dumps(_m, indent=2, ensure_ascii=False) + ("\n" if F[MJ].endswith("\n") else "")

for p, t in F.items():
    open(p, "w", encoding="utf-8").write(t)
open("fieldsim.js", "w", encoding="utf-8").write(base64.b64decode(FIELDSIM).decode("utf-8"))
